('cmngstas30072x43qmlzrijjy', '彼は新車を買って、なんと現金で支払ったそうだ。', '彼は新車を買って、なんと現金で支払ったそうだ。', '听说他买了新车，竟然是用现金支付的。', '/audios/vocabulary/anki/legacy/1775093457385-N2-01-06-34.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.899+00:00'),
('cmngstat30075x43qx2x89nmo', '東京23区面積を合計すると、2,187km²になる。', '東京23区面積を合計すると、2,187km2になる。', '东京23区的面积合计为2,187平方公里。', '/audios/vocabulary/anki/legacy/1775093457391-N2-01-06-36.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.935+00:00'),
('cmnhkybry0002r73qvmc2mwtq', 'そうではなくて、その人がいる集団と集団全体の知的パフォーマンスによって、合成的に語られる。', 'そうではなくて、その人がいる集団と集団全体の知的パフォーマンスによって、合成的に語られる。', NULL, NULL, '📄 阅读：', '/reading/articles/a1ddf2b0-c287-5abb-95b7-8f8b5660a2c1', 'ARTICLE_TEXT', 'a1ddf2b0-c287-5abb-95b7-8f8b5660a2c1', '2026-04-02T05:38:42.718+00:00'),
('cmniztfvr000qx23qv1lcaes8', 'しかしそれが進めば、社会のなかで同調圧力が強まり、社会そのものが萎縮してしまうのだろうか。', 'しかしそれが進めば、社会のなかで同調圧力が強まり、社会そのものが萎縮してしまうのだろうか。', NULL, NULL, '📄 阅读：', '/reading/articles/66f1466e-ed8f-5b10-8a9e-5d0e075d66d2', 'ARTICLE_TEXT', '66f1466e-ed8f-5b10-8a9e-5d0e075d66d2', '2026-04-03T05:22:35.175+00:00'),
('cmnlcukkq00471x3qbygervy8', 'それどころか、都合よく記憶同士を合成したり、書き換えたりすることも行われます。', 'それどころか、都合よく記憶同士を合成したり、書き換えたりすることも行われます。', NULL, NULL, '阅读：', '/reading/articles/b782b626-ffd0-5d0b-83ac-004c01eeb060', 'ARTICLE_TEXT', 'b782b626-ffd0-5d0b-83ac-004c01eeb060', '2026-04-04T21:02:55.274+00:00'),
('cmnldinr5005k1x3qiz3xl56x', 'というのも、テクノロジーの発達によって、不完全な人間の記憶力はどんどん補完されるようになってきており、実際にその仕組みは社会でも利用され始めているからです。', 'というのも、テクノロジーの発達によって、不完全な人間の記憶力はどんどん補完されるようになってきており、実際にその仕組みは社会でも利用され始めているからです。', NULL, NULL, '阅读：', '/reading/articles/b782b626-ffd0-5d0b-83ac-004c01eeb060', 'ARTICLE_TEXT', 'b782b626-ffd0-5d0b-83ac-004c01eeb060', '2026-04-04T21:21:39.137+00:00'),
('cmnlcxjfr004f1x3qi0ozrnj2', '場合によっては、自分の昔の意図と現在の価値観との記憶が混在してしまう……というような事態も生じたりしてしまうわけです。', '場合によっては、自分の昔の意図と現在の価値観との記憶が混在してしまう......というような事態も生じたりしてしまうわけです。', NULL, NULL, '阅读：', '/reading/articles/b782b626-ffd0-5d0b-83ac-004c01eeb060', 'ARTICLE_TEXT', 'b782b626-ffd0-5d0b-83ac-004c01eeb060', '2026-04-04T21:05:13.767+00:00'),
('cmnhognxg0004083qa0tg9lde', '「赤ちゃんのときはどんな音でも区別できるのに、成長するとできなくなる」といわれるのは、決して聞き分け能力の劣化ではなく、日本語の音体系に対応して「区別しないものを見いだし、同じと見なすことを学ぶ」という変化なのだ。', '「赤ちゃんのときはどんな音でも区別できるのに、成長するとできなくなる」といわれるのは、決して聞き分け能力の劣化ではなく、日本語の音体系に対応して「区別しないものを見いだし、同じと見なすことを学ぶ」という変化なのだ。', NULL, NULL, '📄 阅读：', '/reading/articles/9534d7f7-aa39-5fbf-b174-87581353c310', 'ARTICLE_TEXT', '9534d7f7-aa39-5fbf-b174-87581353c310', '2026-04-02T07:16:57.124+00:00');

INSERT OR IGNORE INTO "VocabularySentence" ("id", "text", "normalizedText", "translation", "audioFile", "source", "sourceUrl", "sourceType", "sourceId", "createdAt") VALUES
('cmnlcyvl3004j1x3qnqxptf2p', '嫌な思い出を忘ることもできず、周囲に合わせるための都合のよい記憶の書き換えもできず、かえってつらい人生を送ることになるでしょう。', '嫌な思い出を忘ることもできず、周囲に合わせるための都合のよい記憶の書き換えもできず、かえってつらい人生を送ることになるでしょう。', NULL, NULL, '阅读：', '/reading/articles/b782b626-ffd0-5d0b-83ac-004c01eeb060', 'ARTICLE_TEXT', 'b782b626-ffd0-5d0b-83ac-004c01eeb060', '2026-04-04T21:06:16.167+00:00'),
('cmngstaej004bx43ql6h6ap3t', '古新聞をひもで縛る。', '古新聞をひもで縛る。', '用绳子把旧报纸捆起来。', '/audios/vocabulary/anki/legacy/1775093457271-N2-01-05-06.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.411+00:00'),
('cmngstag0004nx43q18alp4v9', '針に糸を通す。', '針に糸を通す。', '把线穿过针。', '/audios/vocabulary/anki/legacy/1775093457284-N2-01-05-14.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.464+00:00'),
('cmngstagc004qx43qe1ez6q80', 'ビールの栓を抜く。', 'ビールの栓を抜く。', '拔掉啤酒的瓶塞。', '/audios/vocabulary/anki/legacy/1775093457286-N2-01-05-16.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.476+00:00'),
('cmngstagw004tx43qsszekpp0', 'うどんの湯気で眼鏡がくもってしまった。', 'うどんの湯気で眼鏡がくもってしまった。', '乌冬面的热气让眼镜起雾了。', '/audios/vocabulary/anki/legacy/1775093457288-N2-01-05-18.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.496+00:00'),
('cmngstah8004wx43q0c9ezbgz', '私の部屋は南向きで日当たりがいい。', '私の部屋は南向きで日当たりがいい。', '我的房间朝南，采光很好。', '/audios/vocabulary/anki/legacy/1775093457293-N2-01-05-20.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.508+00:00'),
('cmngstam50062x43qmarrve0k', '朝晩は冷え込むが、日中は穏やかな天気が続いている。', '朝晩は冷え込むが、日中は穏やかな天気が続いている。', '早晚很冷，但白天持续着温和的天气。', '/audios/vocabulary/anki/legacy/1775093457344-N2-01-06-10.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.685+00:00'),
('cmngstahl004zx43q44mszcse', '昨夜は一人でワイン一びんを空にした。', '昨夜は一人でワイン一びんを空にした。', '昨晚一个人喝光了一瓶红酒。', '/audios/vocabulary/anki/legacy/1775093457296-N2-01-05-22.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.521+00:00'),
('cmngstahx0052x43qczq7lsn1', '地震で家が斜めに傾いた。', '地震で家が斜めに傾いた。', '因为地震，房子倾斜了。', '/audios/vocabulary/anki/legacy/1775093457302-N2-01-05-24.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.533+00:00'),
('cmngstai90055x43qn7lpexbs', '会社に応募するにあたり、履歴書を書いた。', '会社に応募するにあたり、履歴書を書いた。', '在应聘公司时，写了简历。', '/audios/vocabulary/anki/legacy/1775093457305-N2-01-05-26.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.545+00:00'),
('cmngstain0058x43qyh71drnh', 'うちの父は、釣りを娯楽とした楽しんでいる。', 'うちの父は、釣りを娯楽とした楽しんでいる。', '我的父亲把钓鱼当作娱乐来享受。', '/audios/vocabulary/anki/legacy/1775093457309-N2-01-05-28.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.559+00:00'),
('cmngstaj1005bx43qcn58iwl1', '友人に結婚式の司会を頼んだ。', '友人に結婚式の司会を頼んだ。', '我请朋友担任婚礼的主持人。', '/audios/vocabulary/anki/legacy/1775093457313-N2-01-05-30.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.573+00:00'),
('cmngstaje005ex43qfa07vdzo', '新入社員を歓迎する会が開かれた。', '新入社員を歓迎する会が開かれた。', '举行了欢迎新员工的聚会。', '/audios/vocabulary/anki/legacy/1775093457318-N2-01-05-32.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.586+00:00'),
('cmnldeaj5005d1x3qn4ajl27v', 'したがって、人間の能力の一部に過ぎない記憶力をことさら重要視する現代の教育や受験制度は、せっかく最適化されてきたはずの人類の生存戦略をかえってゆがめてしまっている可能性があるのではないかと思います。', 'したがって、人間の能力の一部に過ぎない記憶力をことさら重要視する現代の教育や受験制度は、せっかく最適化されてきたはずの人類の生存戦略をかえってゆがめてしまっている可能性があるのではないかと思います。', NULL, NULL, '阅读：', '/reading/articles/b782b626-ffd0-5d0b-83ac-004c01eeb060', 'ARTICLE_TEXT', 'b782b626-ffd0-5d0b-83ac-004c01eeb060', '2026-04-04T21:18:15.377+00:00'),
('cmngbb6pl0002tg3qeudo55y9', 'コミュニケーション能力をめぐる競争が激しい社会は、それにつまずいてしまった人にとても冷淡だ。', 'コミュニケーション能力をめぐる競争が激しい社会は、それにつまずいてしまった人にとても冷淡だ。', NULL, NULL, '📄 阅读：7.0', '/reading/articles/66f1466e-ed8f-5b10-8a9e-5d0e075d66d2', NULL, NULL, '2026-04-01T08:21:00.346+00:00'),
('cmngc9x0n0002o63qh2g7gu9v', 'そこでは、組織をまとめあげる、アイディアをだす、交渉する、プレゼンをする、ディスカッションをするといった、高いコミュニケーション能力が必要とされる活動がどうしても物を言う。', 'そこでは、組織をまとめあげる、アイディアをだす、交渉する、プレゼンをする、ディスカッションをするといった、高いコミュニケーション能力が必要とされる活動がどうしても物を言う。', NULL, NULL, '📄 阅读：7.0', '/reading/articles/66f1466e-ed8f-5b10-8a9e-5d0e075d66d2', NULL, NULL, '2026-04-01T08:48:00.743+00:00'),
('cmngstamg0065x43qm6uvzk5x', '急な用事で、旅行の日程を変えた。', '急な用事で、旅行の日程を変えた。', '因为有急事，改变了旅行的日程。', '/audios/vocabulary/anki/legacy/1775093457347-N2-01-06-12.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.696+00:00'),
('cmngstamt0068x43qx7thhgu5', '日光は東京から日帰りで行けます。', '日光は東京から日帰りで行けます。', '日光可以从东京当天往返。', '/audios/vocabulary/anki/legacy/1775093457350-N2-01-06-14.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.709+00:00'),
('cmngstajq005hx43qaa8raugt', '銀行の窓口には大勢の人が並んでいた。', '銀行の窓口には大勢の人が並んでいた。', '银行的窗口排着很多人。', '/audios/vocabulary/anki/legacy/1775093457320-N2-01-05-34.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.598+00:00'),
('cmngstak2005kx43qn1g7yd00', '入学の手続きをする。', '入学の手続きをする。', '办理入学手续。', '/audios/vocabulary/anki/legacy/1775093457324-N2-01-05-36.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.611+00:00'),
('cmngstake005nx43q6tc9v6na', '駅からうちまで、徒歩10分です。', '駅からうちまで、徒歩10分です。', '从车站到家，步行10分钟。', '/audios/vocabulary/anki/legacy/1775093457327-N2-01-05-38.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.622+00:00'),
('cmngstaks005qx43qwaxsw4qk', '日曜日の都心は駐車するところがない。', '日曜日の都心は駐車するところがない。', '星期天的市中心没有停车的地方。', '/audios/vocabulary/anki/legacy/1775093457331-N2-01-06-02.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.636+00:00'),
('cmngstali005wx43qtxaz5798', 'あの店は、平日は9時まで営業している。', 'あの店は、平日は9時まで営業している。', '那家店在工作日营业到9点。', '/audios/vocabulary/anki/legacy/1775093457337-N2-01-06-06.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.662+00:00'),
('cmngstalu005zx43q7yu3gxwt', '日付を書く。', '日付を書く。', '写上日期。', '/audios/vocabulary/anki/legacy/1775093457340-N2-01-06-08.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.674+00:00'),
('cmngstan7006bx43qq4q0enis', '子どもだちが教室に順序よく並んで入っていく。', '子どもだちが教室に順序よく並んで入っていく。', '孩子们按顺序排队进入教室。', '/audios/vocabulary/anki/legacy/1775093457354-N2-01-06-16.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.723+00:00'),
('cmngstavn007ex43q9jngl96b', '来年度の予算を立てる。', '来年度の予算を立てる。', '制定下一年度的预算。', '/audios/vocabulary/anki/legacy/1775093457405-N2-01-07-06.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.027+00:00'),
('cmngstap7006ex43qmjmnbc0v', '3月から4月は、うちの会社にとって忙しい時期だ。', '月から4月は、うちの会社にとって忙しい時期だ。', '3月到4月是我们公司很忙的时期。', '/audios/vocabulary/anki/legacy/1775093457357-N2-01-06-18.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.795+00:00'),
('cmngstapj006hx43qndehi5pb', '駅前は昔は畑だったが、現在は大きなショッピングセンターになっている。', '駅前は昔は畑だったが、現在は大きなショッピングセンターになっている。', '车站前以前是田地，但现在成了一个大型购物中心。', '/audios/vocabulary/anki/legacy/1775093457361-N2-01-06-20.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.807+00:00'),
('cmngstapv006kx43qev2bbcvy', '急病人が出たため、列車は臨時にこの駅に停車した。', '急病人が出たため、列車は臨時にこの駅に停車した。', '因为出现了急症病人，列车临时停靠在了这个车站。', '/audios/vocabulary/anki/legacy/1775093457365-N2-01-06-22.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.820+00:00'),
('cmngstaq7006nx43qusk6svvk', '旅行の費用をためる。', '旅行の費用をためる。', '攒旅行的费用。', '/audios/vocabulary/anki/legacy/1775093457368-N2-01-06-24.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.831+00:00'),
('cmngstav3007bx43q22u7dbc1', '今年は支出が収入を上回って赤字になった。', '今年は支出が収入を上回って赤字になった。', '今年的支出超过了收入，出现了赤字。', '/audios/vocabulary/anki/legacy/1775093457401-N2-01-07-04.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.007+00:00'),
('cmngstawa007hx43qdt50958r', '企業が利益を追求するのは当然だ。', '企業が利益を追求するのは当然だ。', '企业追求利益是理所当然的。', '/audios/vocabulary/anki/legacy/1775093457413-N2-01-07-08.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.050+00:00'),
('cmngstawq007kx43q3m0ozm1r', '今月は支出が多く、家計は赤字だった。', '今月は支出が多く、家計は赤字だった。', '这个月支出很多，家庭收支是赤字。', '/audios/vocabulary/anki/legacy/1775093457418-N2-01-07-10.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.066+00:00'),
('cmngstax6007nx43qc25iczz8', '宣伝に経費をかけたので、売り上げが伸びた。', '宣伝に経費をかけたので、売り上げが伸びた。', '因为在宣传上花了经费，所以销售额增长了。', '/audios/vocabulary/anki/legacy/1775093457443-N2-01-07-12.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.082+00:00'),
('cmngstay6007tx43qutote36z', '隣の家の窓ガラスを割ってしまったので、修理代を弁償した。', '隣の家の窓ガラスを割ってしまったので、修理代を弁償した。', '因为把邻居家的窗户玻璃打碎了，所以赔偿了修理费。', '/audios/vocabulary/anki/legacy/1775093457453-N2-01-07-16.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:59.118+00:00'),
('cmngst9wk0016x43q7i9gwscs', '医学の進歩によって、人間の寿命は100年前に比べるとずいぶん伸びた。', '医学の進歩によって、人間の寿命は100年前に比べるとずいぶん伸びた。', '由于医学的进步，人类的寿命与100年前相比延长了很多。', '/audios/vocabulary/anki/legacy/1775093457093-1-02-30-07bae14828f5ebd7702bf936e585224b3e4dd8a5.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.764+00:00'),
('cmngst9zc001hx43q3u7ihnmw', '「あなたの性格の長所と短所を言ってください」', '「あなたの性格の長所と短所を言ってください」', '“请说出你性格的优缺点。”', '/audios/vocabulary/anki/legacy/1775093457118-N2-1-03-04.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.864+00:00'),
('cmngst9zr001kx43qdhkse4qn', '子どもたちの個性を伸ばすような教育がしたい。', '子どもたちの個性を伸ばすような教育がしたい。', '我想进行能发展孩子们个性的教育。', '/audios/vocabulary/anki/legacy/1775093457122-N2-1-03-06.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.879+00:00'),
('cmngsta08001nx43q330f2h8o', '私の左利きは親からの遺伝だ。', '私の左利きは親からの遺伝だ。', '我的左撇子是父母遗传的。', '/audios/vocabulary/anki/legacy/1775093457129-N2-1-03-08.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.896+00:00'),
('cmngsta10001qx43qxcyzzo05', '彼女の動作は優雅で美しい。', '彼女の動作は優雅で美しい。', '她的动作优雅而美丽。', '/audios/vocabulary/anki/legacy/1775093457133-N2-1-03-10.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.924+00:00'),
('cmngsta1g001tx43quj1lx35k', '子どもは何でも親のまねをしたがるものだ。', '子どもは何でも親のまねをしたがるものだ。', '小孩子总是想模仿父母的任何事情。', '/audios/vocabulary/anki/legacy/1775093457137-N2-1-03-12.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:57.940+00:00'),
('cmngstaub0078x43q2q4zvtcv', '彼は喫茶店を経営して収入を得ている。', '彼は喫茶店を経営して収入を得ている。', '他通过经营咖啡店获得收入。', '/audios/vocabulary/anki/legacy/1775093457397-N2-01-07-02.mp3', 'Unit1', '/manage/import?type=anki', NULL, NULL, '2026-04-01T16:30:58.979+00:00');

