('cmnjx7h4o001dvz3qbr6p14hl', '1f5b4eeb-4d32-5bc7-b5e6-d381a0701335', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"order":21,"legacy":{"quizId":"cmnj4hkqz004ex23q6x7u9slg","lessonId":null,"passageId":null},"targetWord":"抜き打ち","optionLabelFormat":"numeric","customOptionLabels":[]}', '抜き打ち', NULL, '[{"id":"cmnjx7h4p001evz3qqx5enydb","text":"さっきまで晴れていたのに、抜き打ちで雨が降り出した。"},{"id":"cmnjx7h4p001fvz3q5kpz7xml","text":"前を走っている車が抜き打ちでブレーキをかけた。"},{"id":"cmnjx7h4p001gvz3qqo6aknaa","text":"工場への立ち入り検査は、抜き打ちで実施された。"},{"id":"cmnjx7h4p001hvz3qt0ly2sv0","text":"家族で旅行に行ったら、学校の友達と抜き打ちで会った。"}]', 'cmnjx7h4p001gvz3qqo6aknaa', NULL, NULL, '2026-04-03T20:57:17.304+00:00', '2026-08-08T06:32:17.960+00:00', 21),
('cmnjx7h6m001nvz3qeoygzjwr', '1f5b4eeb-4d32-5bc7-b5e6-d381a0701335', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"order":23,"legacy":{"quizId":"cmnj4hkqz004ex23q6x7u9slg","lessonId":null,"passageId":null},"targetWord":"緻密","optionLabelFormat":"numeric","customOptionLabels":[]}', '緻密', NULL, '[{"id":"cmnjx7h6n001ovz3q6q61359z","text":"縫さんは記憶力がよく、知人の住所や電話番号をすべて緻密に覚えているそうだ。"},{"id":"cmnjx7h6n001pvz3qotbk2im0","text":"旅行先での宿の主人の緻密さにてなしに感動した。"},{"id":"cmnjx7h6n001qvz3qk8ide2us","text":"階段で転ばないように、歩き方緻密に上っていった。"},{"id":"cmnjx7h6n001rvz3qkfywupce","text":"緻密な観察が新しい微生物の発見につながった。"}]', 'cmnjx7h6n001rvz3qkfywupce', NULL, NULL, '2026-04-03T20:57:17.374+00:00', '2026-08-08T06:32:17.963+00:00', 23),
('cmnjx7h7o001svz3qwjrk9xml', '1f5b4eeb-4d32-5bc7-b5e6-d381a0701335', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"order":24,"legacy":{"quizId":"cmnj4hkqz004ex23q6x7u9slg","lessonId":null,"passageId":null},"targetWord":"迫力","optionLabelFormat":"numeric","customOptionLabels":[]}', '迫力', NULL, '[{"id":"cmnjx7h7p001tvz3qqcs01cet","text":"新しい掃除機は、ごみを吸う迫力が以前の約2倍となっている。"},{"id":"cmnjx7h7p001uvz3q7n911zb1","text":"初めて動物園で見たライオンは、体が大きくて迫力があった。"},{"id":"cmnjx7h7p001vvz3qelf381t4","text":"天気予報によると、午後から雨の迫力が増していくらしい。"},{"id":"cmnjx7h7p001wvz3qo2rchp0e","text":"高橋さんは一日中作業しても元気なので、迫力があると思う。"}]', 'cmnjx7h7p001uvz3q7n911zb1', NULL, NULL, '2026-04-03T20:57:17.412+00:00', '2026-08-08T06:32:17.964+00:00', 24),
