('c14ea22b-804b-4490-bcdc-b5ac0a5b32a4', '9bdb0939-6c9b-41bd-9042-eadfe03acced', 'CHOICE_QUIZ', 'SYNONYM_REPLACEMENT', '{"targetWord":"やむをえず","optionLabelFormat":"numeric","customOptionLabels":[]}', '激しい雨のため、やむをえず試合は延期することになった。', NULL, '[{"id":"opt_1","text":"しかたなく"},{"id":"opt_2","text":"まもなく"},{"id":"opt_3","text":"思いがけなく"},{"id":"opt_4","text":"限りなく"}]', '["opt_1"]', NULL, NULL, '2026-04-09T00:14:30.006+00:00', '2026-08-08T06:32:18.104+00:00', 19),
('87917d8c-60b4-432f-87fe-b702b85381ab', '9bdb0939-6c9b-41bd-9042-eadfe03acced', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"targetWord":"調達","optionLabelFormat":"numeric","customOptionLabels":[]}', '調達', NULL, '[{"id":"opt_1","text":"新しい事業のために、資金を調達しなければならない。"},{"id":"opt_2","text":"インターネットで奨学金の申請方法を調達した。"},{"id":"opt_3","text":"希望の職種に就くためには、早めに必要な資格を調達した方がいい。"},{"id":"opt_4","text":"環境問題に対する各国の若者の意識を調達した。"}]', '["opt_1"]', NULL, NULL, '2026-04-09T00:19:13.030+00:00', '2026-08-08T06:32:18.105+00:00', 20),
('a9bc4381-3a1f-4a0d-be9f-34630785d975', '9bdb0939-6c9b-41bd-9042-eadfe03acced', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"targetWord":"細心","optionLabelFormat":"numeric","customOptionLabels":[]}', '細心', NULL, '[{"id":"opt_1","text":"初めて一人で海外旅行をしたときは、細心の思いをした。"},{"id":"opt_2","text":"この二つの言葉は似ているが、細心のところでは意味が異なる。"},{"id":"opt_3","text":"美術品の運搬には、細心の注意を払う必要がある。"},{"id":"opt_4","text":"イベントの概要は伺いましたが、細心の説明はまだです。"}]', '["opt_3"]', NULL, NULL, '2026-04-09T00:19:13.117+00:00', '2026-08-08T06:32:18.106+00:00', 21),
('17da99a8-a693-43ec-858f-36977029194b', '9bdb0939-6c9b-41bd-9042-eadfe03acced', 'CHOICE_QUIZ', 'WORD_DISTINCTION', '{"targetWord":"意地","optionLabelFormat":"numeric","customOptionLabels":[]}', '意地', NULL, '[{"id":"opt_1","text":"彼は何がやりたいのか、意地がはっきりしない。"},{"id":"opt_2","text":"そう意地を張らずに、すなおに謝った方がいいよ。"},{"id":"opt_3","text":"会議で、この調査の意地を説明した。"},{"id":"opt_4","text":"わが社は顧客の意地に沿った商品開発を目指している。"}]', '["opt_2"]', NULL, NULL, '2026-04-09T00:19:13.182+00:00', '2026-08-08T06:32:18.108+00:00', 22);

